CREATE TABLE schema_version (version INTEGER NOT NULL);
INSERT INTO schema_version VALUES(7);
CREATE TABLE ownership (instance_id TEXT PRIMARY KEY, container_id TEXT NOT NULL, container_name TEXT NOT NULL, network_name TEXT NOT NULL, image_digest TEXT NOT NULL, data_path TEXT NOT NULL, created_at TEXT NOT NULL, runtime_generation INTEGER NOT NULL DEFAULT 1, application_id TEXT NOT NULL DEFAULT '', release_id TEXT NOT NULL DEFAULT '', exposure_mode TEXT NOT NULL DEFAULT 'internal', service_id TEXT NOT NULL DEFAULT '', host_address TEXT NOT NULL DEFAULT '', host_port INTEGER NOT NULL DEFAULT 0, container_port INTEGER NOT NULL DEFAULT 0, service_protocol TEXT NOT NULL DEFAULT '');
CREATE TABLE receipts (operation_id TEXT PRIMARY KEY, request_hash TEXT NOT NULL, operation_type TEXT NOT NULL, instance_id TEXT NOT NULL, phase TEXT NOT NULL, outcome TEXT NOT NULL, container_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE reconciliation (instance_id TEXT PRIMARY KEY, classification TEXT NOT NULL, observed_at TEXT NOT NULL, summary TEXT NOT NULL);
CREATE TABLE component_ownership (installation_id TEXT NOT NULL, component_id TEXT NOT NULL, container_id TEXT NOT NULL, container_name TEXT NOT NULL, network_name TEXT NOT NULL, image_digest TEXT NOT NULL, runtime_generation INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(installation_id,component_id));
CREATE TABLE installation_secrets (installation_id TEXT NOT NULL, component_id TEXT NOT NULL DEFAULT '', name TEXT NOT NULL, value TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(installation_id,component_id,name));
CREATE TABLE hardware_assignments (installation_id TEXT NOT NULL, component_id TEXT NOT NULL DEFAULT '', device_class TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('device','cpu')), vendor TEXT NOT NULL DEFAULT '', stable_id TEXT NOT NULL DEFAULT '', resolved_devices TEXT NOT NULL DEFAULT '[]', runtime_generation INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(installation_id,component_id,device_class));
CREATE TABLE trusted_storage_roots (root_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, canonical_path TEXT NOT NULL UNIQUE, allowed_mode TEXT NOT NULL CHECK(allowed_mode IN ('read-only','read-write')), device_major INTEGER NOT NULL, device_minor INTEGER NOT NULL, inode INTEGER NOT NULL, filesystem_type TEXT NOT NULL, mount_source TEXT NOT NULL, mount_point TEXT NOT NULL, network_backed INTEGER NOT NULL CHECK(network_backed IN (0,1)), created_at TEXT NOT NULL);
CREATE TABLE external_storage_bindings (installation_id TEXT NOT NULL, component_id TEXT NOT NULL DEFAULT '', slot_id TEXT NOT NULL, root_id TEXT NOT NULL, access_mode TEXT NOT NULL CHECK(access_mode IN ('read-only','read-write')), container_path TEXT NOT NULL, runtime_generation INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(installation_id,component_id,slot_id), FOREIGN KEY(root_id) REFERENCES trusted_storage_roots(root_id) ON DELETE RESTRICT);
